  is_public: boolean;
};
type Track = { public_id: string; name: string; description: string };
type Prize = { public_id: string; name: string; kind: string; track: string | null };
type Dashboard = {
  event: Event;
  track_count: number;
  base_prize_count: number;
  configuration_checks: string[];
