    void run(async () => {
      await request<Event>(eventBase + "status/", "POST", { status });
      await refresh();
    });
  }
  const selected = dashboard?.event;
  const nextStatus = selected?.status === "draft" ? "open"
    : selected?.status === "open" ? "closed"
    : selected?.status === "closed" ? "archived" : null;

  return <section aria-label="Event dashboard">
    <h1>Events</h1>
    {error && <p role="alert">{error}</p>}
    <form onSubmit={createEvent}>
      <h2>Create event</h2>
      <label>Name <input value={name} onChange={(e) => setName(e.target.value)} required /></label>
