    <nav aria-label="Workspace events">
      {events.map((item) => <button key={item.public_id} type="button"
        aria-current={selectedId === item.public_id ? "page" : undefined}
        onClick={() => choose(item.public_id)}>{item.name} ({item.status})</button>)}
    </nav>
    {selected && <article>
      <h2>{selected.name}</h2>
      <p>Status: {selected.status} · {selected.is_public ? "Public" : "Private"}</p>
      {dashboard.configuration_checks.length > 0 && <section aria-label="Configuration checks">
        <h3>Configuration checks</h3>
        <ul>{dashboard.configuration_checks.map((check) => <li key={check}>{check}</li>)}</ul>
      </section>}
      <form onSubmit={saveSettings} key={selected.public_id + selected.updated_at}>
        <h3>Settings</h3>
        <label>Name <input name="name" defaultValue={selected.name} required /></label>
        <label>Timezone <input name="timezone" defaultValue={selected.timezone} required /></label>
        <label>Start <input name="starts_at" type="datetime-local" defaultValue={selected.starts_at?.slice(0, 16)} /></label>
        <label>End <input name="ends_at" type="datetime-local" defaultValue={selected.ends_at?.slice(0, 16)} /></label>
