          </select></label>
          <label>Track <select value={prizeTrack} onChange={(e) => setPrizeTrack(e.target.value)}>
            <option value="">All tracks</option>{tracks.map((track) => <option key={track.public_id} value={track.public_id}>{track.name}</option>)}
          </select></label>
          {prizeKind === "cash" && <><label>Amount <input type="number" min="0" step="0.01" value={prizeAmount}
            onChange={(e) => setPrizeAmount(e.target.value)} required /></label>
            <label>Currency <input maxLength={3} value={prizeCurrency}
              onChange={(e) => setPrizeCurrency(e.target.value)} required /></label></>}
          <button disabled={busy}>Add prize</button>
        </form>
      </section>
    </article>}
  </section>;
}
